#include <iostream>
#include <vector>

bool piezas_validas(int piezas) {
    return piezas >= 0 && piezas <= 10;
}

int estimar(int piezas) {
    if (!piezas_validas(piezas)) { return -1; }
    if (piezas == 0) { return 0; }
    return 3 + 2 * piezas;
}

int main() {
    std::vector<int> piezas{1, 12, 4, 0};
    int validos{0};
    int rechazados{0};
    int minutos{0};
    for (int cantidad : piezas) {
        int resultado{estimar(cantidad)};
        if (resultado == -1) {
            ++rechazados;
        } else {
            ++validos;
            minutos += resultado;
        }
    }
    std::cout << validos << ":" << rechazados << ":" << minutos;
    return 0;
}

